7	import { spawn } from 'node:child_process';
8	import { type FileSystemService } from './fileSystemService.js';
9	import { type SandboxManager } from './sandboxManager.js';
10	import { debugLogger } from '../utils/debugLogger.js';
11	import { isNodeError } from '../utils/errors.js';
