196	  baseDir: string,
197	  maxDepth = 1,
198	): Promise<string[]> {
199	  const secrets: string[] = [];
200	  const skipDirs = new Set([
201	    'node_modules',
202	    '.git',
203	    '.venv',
204	    '__pycache__',
205	    'dist',
206	    'build',
207	    '.next',
208	    '.idea',
209	    '.vscode',
210	  ]);
211	
212	  async function walk(dir: string, depth: number) {
213	    if (depth > maxDepth) return;
214	    try {
215	      const entries = await fs.readdir(dir, { withFileTypes: true });
216	      for (const entry of entries) {
217	        const fullPath = path.join(dir, entry.name);
218	        if (entry.isDirectory()) {
219	          if (!skipDirs.has(entry.name)) {
220	            await walk(fullPath, depth + 1);
221	          }
222	        } else if (entry.isFile()) {
223	          if (isSecretFile(entry.name)) {
224	            secrets.push(fullPath);
225	          }
226	        }
227	      }
228	    } catch {
229	      // Ignore read errors
230	    }
231	  }
232	
233	  await walk(baseDir, 1);
234	  return secrets;
235	}
