47	function getSeccompBpfPath(): string {
48	  if (cachedBpfPath) return cachedBpfPath;
49	
50	  const arch = os.arch();
51	  let AUDIT_ARCH: number;
52	  let SYS_ptrace: number;
53	
54	  if (arch === 'x64') {
55	    AUDIT_ARCH = 0xc000003e; // AUDIT_ARCH_X86_64
56	    SYS_ptrace = 101;
57	  } else if (arch === 'arm64') {
58	    AUDIT_ARCH = 0xc00000b7; // AUDIT_ARCH_AARCH64
59	    SYS_ptrace = 117;
60	  } else if (arch === 'arm') {
61	    AUDIT_ARCH = 0x40000028; // AUDIT_ARCH_ARM
62	    SYS_ptrace = 26;
63	  } else if (arch === 'ia32') {
64	    AUDIT_ARCH = 0x40000003; // AUDIT_ARCH_I386
65	    SYS_ptrace = 26;
66	  } else {
67	    throw new Error(`Unsupported architecture for seccomp filter: ${arch}`);
68	  }
69	
70	  const EPERM = 1;
71	  const SECCOMP_RET_KILL_PROCESS = 0x80000000;
72	  const SECCOMP_RET_ERRNO = 0x00050000;
73	  const SECCOMP_RET_ALLOW = 0x7fff0000;
74	
75	  const instructions = [
76	    { code: 0x20, jt: 0, jf: 0, k: 4 }, // Load arch
77	    { code: 0x15, jt: 1, jf: 0, k: AUDIT_ARCH }, // Jump to kill if arch != native arch
78	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_KILL_PROCESS }, // Kill
79	
80	    { code: 0x20, jt: 0, jf: 0, k: 0 }, // Load nr
81	    { code: 0x15, jt: 0, jf: 1, k: SYS_ptrace }, // If ptrace, jump to ERRNO
82	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ERRNO | EPERM }, // ERRNO
83	
84	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ALLOW }, // Allow
85	  ];
86	
87	  const buf = Buffer.alloc(8 * instructions.length);
88	  for (let i = 0; i < instructions.length; i++) {
89	    const inst = instructions[i];
90	    const offset = i * 8;
91	    buf.writeUInt16LE(inst.code, offset);
92	    buf.writeUInt8(inst.jt, offset + 2);
93	    buf.writeUInt8(inst.jf, offset + 3);
94	    buf.writeUInt32LE(inst.k, offset + 4);
95	  }
96	
97	  const tempDir = fs.mkdtempSync(join(os.tmpdir(), 'gemini-cli-seccomp-'));
98	  const bpfPath = join(tempDir, 'seccomp.bpf');
99	  fs.writeFileSync(bpfPath, buf);
100	  cachedBpfPath = bpfPath;
101	
102	  // Cleanup on exit
103	  process.on('exit', () => {
104	    try {
105	      fs.rmSync(tempDir, { recursive: true, force: true });
106	    } catch {
107	      // Ignore errors
108	    }
109	  });
110	
111	  return bpfPath;
112	}
