11	
12	/**
13	 * Validates if the requested paths are within the allowed workspace or allowed paths.
14	 */
15	function validatePaths(
16	  paths: string[],
17	  workspace: string,
18	  allowedPaths: string[],
19	): boolean {
20	  for (const p of paths) {
21	    const resolvedPath = path.resolve(p);
22	    const resolvedWorkspace = path.resolve(workspace);
23	    const isInsideWorkspace =
24	      resolvedPath.startsWith(resolvedWorkspace + path.sep) ||
25	      resolvedPath === resolvedWorkspace;
26	
27	    let isInsideAllowed = false;
28	    for (const allowed of allowedPaths) {
29	      const resolvedAllowed = path.resolve(allowed);
30	      if (
31	        resolvedPath.startsWith(resolvedAllowed + path.sep) ||
32	        resolvedPath === resolvedAllowed
33	      ) {
34	        isInsideAllowed = true;
35	        break;
36	      }
37	    }
38	
39	    if (!isInsideWorkspace && !isInsideAllowed) {
40	      return false; // Path traversal or unauthorized access attempt
41	    }
42	  }
43	  return true;
44	}
45	
46	export function handleReadWriteCommands(
47	  req: SandboxRequest,
48	  mergedAdditional: SandboxPermissions,
49	  workspace: string,
50	  allowedPaths: string[] = [],
51	): { command: string; args: string[] } {
52	  let finalCommand = req.command;
53	  let finalArgs = req.args;
54	
55	  if (req.command === '__read') {
56	    finalCommand = '/bin/cat';
57	    if (req.args.length > 0) {
58	      if (validatePaths(req.args, workspace, allowedPaths)) {
59	        mergedAdditional.fileSystem!.read!.push(...req.args);
60	      } else {
61	        throw new Error(
62	          `Sandbox Error: Path traversal or unauthorized access attempt detected in __read: ${req.args.join(', ')}`,
63	        );
64	      }
65	    }
66	  } else if (req.command === '__write') {
67	    finalCommand = '/bin/sh';
68	    finalArgs = ['-c', 'tee -- "$@" > /dev/null', '_', ...req.args];
69	    if (req.args.length > 0) {
70	      if (validatePaths(req.args, workspace, allowedPaths)) {
71	        mergedAdditional.fileSystem!.write!.push(...req.args);
72	      } else {
73	        throw new Error(
74	          `Sandbox Error: Path traversal or unauthorized access attempt detected in __write: ${req.args.join(', ')}`,
75	        );
76	      }
77	    }
78	  }
79	
80	  return { command: finalCommand, args: finalArgs };
81	}
