22	export interface EnterPlanModeParams {
23	  reason?: string;
24	}
25	
26	export class EnterPlanModeTool extends BaseDeclarativeTool<
27	  EnterPlanModeParams,
28	  ToolResult
29	> {
30	  static readonly Name = ENTER_PLAN_MODE_TOOL_NAME;
31	
32	  constructor(
33	    private config: Config,
34	    messageBus: MessageBus,
35	  ) {
36	    super(
37	      EnterPlanModeTool.Name,
38	      'Enter Plan Mode',
39	      ENTER_PLAN_MODE_DEFINITION.base.description!,
40	      Kind.Plan,
41	      ENTER_PLAN_MODE_DEFINITION.base.parametersJsonSchema,
42	      messageBus,
43	    );
44	  }
45	
46	  protected createInvocation(
47	    params: EnterPlanModeParams,
48	    messageBus: MessageBus,
49	    toolName: string,
50	    toolDisplayName: string,
51	  ): EnterPlanModeInvocation {
52	    return new EnterPlanModeInvocation(
53	      params,
54	      messageBus,
55	      toolName,
56	      toolDisplayName,
57	      this.config,
58	    );
59	  }
60	
61	  override getSchema(modelId?: string) {
62	    return resolveToolDeclaration(ENTER_PLAN_MODE_DEFINITION, modelId);
63	  }
64	}
