66	export class EnterPlanModeInvocation extends BaseToolInvocation<
67	  EnterPlanModeParams,
68	  ToolResult
69	> {
70	  private confirmationOutcome: ToolConfirmationOutcome | null = null;
71	
72	  constructor(
73	    params: EnterPlanModeParams,
74	    messageBus: MessageBus,
75	    toolName: string,
76	    toolDisplayName: string,
77	    private config: Config,
78	  ) {
79	    super(params, messageBus, toolName, toolDisplayName);
80	  }
81	
82	  getDescription(): string {
83	    return this.params.reason || 'Initiating Plan Mode';
84	  }
85	
86	  override async shouldConfirmExecute(
87	    abortSignal: AbortSignal,
88	  ): Promise<ToolInfoConfirmationDetails | false> {
89	    const decision = await this.getMessageBusDecision(abortSignal);
90	    if (decision === 'allow') {
91	      return false;
92	    }
93	
94	    if (decision === 'deny') {
95	      throw new Error(
96	        `Tool execution for "${
97	          this._toolDisplayName || this._toolName
98	        }" denied by policy.`,
99	      );
100	    }
101	
102	    // ask_user
103	    return {
104	      type: 'info',
105	      title: 'Enter Plan Mode',
106	      prompt:
107	        'This will restrict the agent to read-only tools to allow for safe planning.',
108	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
109	        this.confirmationOutcome = outcome;
110	        // Policy updates are now handled centrally by the scheduler
111	      },
112	    };
113	  }
114	
115	  async execute(_signal: AbortSignal): Promise<ToolResult> {
116	    if (this.confirmationOutcome === ToolConfirmationOutcome.Cancel) {
117	      return {
118	        llmContent: 'User cancelled entering Plan Mode.',
119	        returnDisplay: 'Cancelled',
120	      };
121	    }
122	
123	    this.config.setApprovalMode(ApprovalMode.PLAN);
124	
125	    return {
126	      llmContent: 'Switching to Plan mode.',
127	      returnDisplay: this.params.reason
128	        ? `Switching to Plan mode: ${this.params.reason}`
129	        : 'Switching to Plan mode',
130	    };
131	  }
132	}
